<template><BioNexusStateDialog ref="dialog" :saving="saving" @confirm="row=>emit('confirm',row)"/></template><script setup>import{ref}from'vue';import BioNexusStateDialog from'@/components/ui/BioNexusStateDialog.vue';defineProps({saving:Boolean});const emit=defineEmits(['confirm']),dialog=ref(null),config={kicker:'Estado de la moneda',isInactive:r=>r?.isActive!==true,activateTitle:'Activar moneda',deactivateTitle:'Inactivar moneda',activateMessage:'La moneda volverá a estar disponible para nuevas operaciones.',deactivateMessage:'La moneda dejará de estar disponible para nuevas operaciones. Los registros existentes conservarán la moneda asignada.',deactivateWarning:r=>r?.isBase?'La moneda base no puede inactivarse.':r?.isLocal?'La moneda local no puede inactivarse.':'',label:r=>r?`${r.name} (${r.code})`:'Moneda seleccionada',dangerOnDeactivate:true};defineExpose({open:r=>dialog.value?.open(r,config),close:()=>dialog.value?.close(),setError:v=>dialog.value?.setError(v),clearError:()=>dialog.value?.clearError()})</script>